const statuses=['Новая','Написали','Ответил','Консультация','В работе','Закрыта'];
const today=()=>new Date().toLocaleDateString('en-CA');
const days=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};
const seed=[['Алина Каримова','Computer Engineering','Новая','Мария',0],['Даниил Петров','Business Administration','Написали','Алексей',-1],['София Алиева','Medicine','Ответил','Мария',0],['Амир Османов','Architecture','Консультация','Алексей',1],['Ева Смирнова','Psychology','В работе','Мария',2],['Максим Волков','Software Engineering','Написали','Алексей',-2]].map((x,i)=>({id:crypto.randomUUID(),name:x[0],program:x[1],status:x[2],owner:x[3],email:`applicant${i+1}@example.com`,phone:'',year:2027,created:new Date(Date.now()-(i+1)*86400000).toISOString(),first:i?new Date(Date.now()-i*86400000).toISOString():null,task:i===0?'Связаться по заявке':i===1||i===5?'Повторно связаться':i===2?'Согласовать консультацию':'Проверить следующий этап',due:days(x[4]),notes:'',history:[{text:'Заявка поступила с сайта (демо)',at:new Date(Date.now()-(i+1)*86400000).toISOString()}]}));
let leads;try{leads=JSON.parse(localStorage.getItem('uni4u-demo-v1'))||seed;if(!Array.isArray(leads))leads=seed}catch{leads=seed}
let selected=null,view='all';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const stamp=s=>s?new Date(s).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Ещё не связались';const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'Не назначено';const overdue=l=>l.due&&l.due<today()&&l.status!=='Закрыта';function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}function persist(){try{localStorage.setItem('uni4u-demo-v1',JSON.stringify(leads))}catch{toast('Не удалось сохранить в браузере')}render()}
statuses.forEach(s=>$('#filter').add(new Option(s,s)));
function render(){const active=leads.filter(l=>l.status!=='Закрыта');const cards=[['Всего заявок',leads.length,'В этом демо'],['Ждут первого контакта',active.filter(l=>!l.first).length,'Нужно написать'],['Просрочено',active.filter(overdue).length,'Следующее действие'],['Ответили',leads.filter(l=>['Ответил','Консультация','В работе'].includes(l.status)).length,'Продолжают диалог']];$('#stats').innerHTML=cards.map((c,i)=>`<div class="stat ${i===2?'alert':''}"><span>${c[0]}</span><b>${c[1]}</b><span>${c[2]}</span></div>`).join('');let data=leads.filter(l=>(view!=='tasks'||(l.task&&l.status!=='Закрыта'))&&(!$('#filter').value||l.status===$('#filter').value)&&`${l.name} ${l.email} ${l.program} ${l.owner}`.toLowerCase().includes($('#search').value.toLowerCase()));if(view==='tasks')data.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));$('#count').textContent=`Заявок: ${data.length}`;$('#rows').innerHTML=data.map(l=>`<tr><td><button class="row-open" data-id="${l.id}">${esc(l.name)}</button><small>${esc(l.program)} · ${l.year}</small></td><td><span class="badge ${l.status==='Новая'?'new':['Ответил','Консультация','В работе'].includes(l.status)?'replied':''}">${esc(l.status)}</span></td><td class="${l.first?'':'muted'}">${stamp(l.first)}<small>Заявка: ${stamp(l.created)}</small></td><td class="${overdue(l)?'overdue':''}">${esc(l.task||'Не назначено')}<small>${date(l.due)}${overdue(l)?' · просрочено':''}</small></td><td>${esc(l.owner)}</td></tr>`).join('');$('#empty').hidden=!!data.length;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openLead(b.dataset.id))}
function openLead(id){selected=leads.find(l=>l.id===id);if(!selected)return;const l=selected;$('#clientName').textContent=l.name;$('#detailBody').innerHTML=`<div class="contact">${esc(l.program)} · поступление ${l.year}<br>${esc(l.email)}${l.phone?'<br>'+esc(l.phone):''}</div><div class="formgrid"><label>Статус<select id="editStatus">${statuses.map(s=>`<option ${l.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Ответственный<input id="editOwner" value="${esc(l.owner)}" required></label><label>Следующее действие<input id="editTask" value="${esc(l.task)}"></label><label>Дата напоминания<input type="date" id="editDue" value="${esc(l.due)}"></label></div><label>Заметки<textarea id="editNotes" rows="3">${esc(l.notes)}</textarea></label><div class="actions" style="margin-top:15px"><button class="primary" id="save">Сохранить изменения</button><button id="contacted">Отметить первый контакт</button></div><div class="section-title">Первое сообщение</div><label>Черновик для клиента<textarea id="message" rows="5"></textarea></label><div class="actions" style="margin-top:12px"><button id="copy">Скопировать</button><button id="email">Открыть в почте</button></div><div class="section-title">История</div><ul class="timeline">${l.history.slice().reverse().map(h=>`<li>${esc(h.text)}<small>${stamp(h.at)}</small></li>`).join('')}</ul>`;$('#message').value=`Здравствуйте, ${l.name.split(' ')[0]}! Вы оставили заявку в Uni4U на поступление в Турцию по направлению ${l.program}. Меня зовут ${l.owner}. Планируете поступать в ${l.year} году? Могу помочь подобрать варианты и рассказать о следующем шаге.`;$('#save').onclick=()=>{const owner=$('#editOwner').value.trim();if(!owner)return toast('Укажите ответственного');const changes=[];const vals={status:$('#editStatus').value,owner,task:$('#editTask').value.trim(),due:$('#editDue').value,notes:$('#editNotes').value};for(const[k,v]of Object.entries(vals))if(l[k]!==v)changes.push(k==='status'?`Статус: ${v}`:k==='due'?`Напоминание: ${date(v)}`:k==='task'?`Действие: ${v||'не назначено'}`:k==='owner'?`Ответственный: ${v}`:'Заметки обновлены');Object.assign(l,vals);if(changes.length)l.history.push({text:changes.join(' · '),at:new Date().toISOString()});persist();$('#detail').close();toast('Изменения сохранены')};$('#contacted').onclick=()=>{if(l.first)return toast('Первый контакт уже отмечен');l.first=new Date().toISOString();if(l.status==='Новая')l.status='Написали';l.history.push({text:'Первый контакт отмечен менеджером',at:l.first});persist();openLead(l.id);toast('Контакт отмечен')};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);toast('Сообщение скопировано')}catch{$('#message').select();toast('Выделено — скопируйте вручную')}};$('#email').onclick=()=>{location.href=`mailto:${encodeURIComponent(l.email)}?subject=${encodeURIComponent('Ваша заявка на поступление — Uni4U')}&body=${encodeURIComponent($('#message').value)}`};if(!$('#detail').open)$('#detail').showModal()}
$('#search').oninput=render;$('#filter').onchange=render;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#title').textContent=view==='all'?'Заявки на поступление':'Следующие действия';render()});$('#add').onclick=()=>$('#new').showModal();$('#closeNew').onclick=()=>$('#new').close();$('#newForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const l={id:crypto.randomUUID(),name:f.get('name').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),program:f.get('program').trim(),year:Number(f.get('year')),owner:f.get('owner').trim(),status:'Новая',created:new Date().toISOString(),first:null,task:'Связаться по заявке',due:today(),notes:'',history:[{text:'Заявка добавлена вручную',at:new Date().toISOString()}]};if(!l.name||!l.program||!l.owner)return toast('Заполните обязательные поля');leads.unshift(l);persist();$('#new').close();e.target.reset();openLead(l.id);toast('Заявка добавлена')};render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_leads',description:'Прочитать заявки в текущем локальном демо',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>leads.map(({id,name,status,task,due})=>({id,name,status,task,due}))})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_lead',description:'Открыть карточку существующей заявки по ID',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute:input=>{if(!input||typeof input.id!=='string'||!leads.some(l=>l.id===input.id))throw new Error('Заявка не найдена');openLead(input.id);return{id:input.id,opened:true}}})).catch(()=>{})}catch{}}

// Guided local demo: no outbound messaging or shared scheduling.
function logFlow(l,text){l.history.push({text,at:new Date().toISOString()})}
function followStage(l){if(['Ответил','Консультация','В работе','Закрыта'].includes(l.status)||l.flow?.reply)return 'stopped';if(!l.first)return 'first';if((l.flow?.followups||0)>=2)return 'done';return 'followup'}
function flowText(l,stage){const name=l.name.split(' ')[0];if(stage==='first')return `Здравствуйте, ${name}! Вы оставили заявку в Uni4U по направлению ${l.program}. Меня зовут ${l.owner}. Планируете поступать в ${l.year} году? Если да, подскажите удобное время для короткой консультации.`;return `${name}, здравствуйте! Возвращаюсь к вашей заявке на ${l.program}. Поступление в Турцию ещё актуально? Можем обсудить варианты на короткой консультации. Если планы изменились, дайте знать — больше не будем напоминать.`}
const originalOpenLead=openLead;
openLead=function(id){originalOpenLead(id);const l=selected;if(!l)return;l.flow ||= {followups:0,reply:null,booking:null};const stage=followStage(l);const box=document.createElement('section');box.className='flow';box.innerHTML=`<div class="section-title">От заявки до консультации <span class="badge new">ДЕМО</span></div><p class="flow-hint">Сообщения здесь только имитируются. Повторные контакты прекращаются после ответа или закрытия заявки.</p><div class="flow-steps"><span class="${l.first?'complete':''}">1. Первый ответ</span><span class="${l.flow.reply?'complete':''}">2. Диалог</span><span class="${l.flow.booking?'complete':''}">3. Консультация</span></div><label>Текст сообщения<textarea id="flowMessage" rows="5"></textarea></label><div class="actions" style="margin-top:12px"><button class="primary" id="flowSend" ${['stopped','done'].includes(stage)?'disabled':''}>${stage==='first'?'Имитировать первый ответ':stage==='followup'?'Имитировать повторный контакт':'Цепочка остановлена'}</button><button id="flowReply">Имитировать ответ клиента</button></div><p class="flow-hint" id="flowState"></p><div class="section-title">Запись на консультацию</div><p class="flow-hint">Выбор времени от лица клиента. Демо не проверяет занятость менеджера и не создаёт событие в календаре.</p><div class="formgrid"><label>Дата<input id="bookingDate" type="date" min="${today()}" value="${l.flow.booking?.date||days(1)}"></label><label>Время (Стамбул)<select id="bookingTime">${['10:00','12:00','14:00','16:00'].map(t=>`<option ${l.flow.booking?.time===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="actions"><button class="primary" id="bookFlow">${l.flow.booking?'Изменить запись':'Подтвердить время (демо)'}</button>${l.flow.booking?'<button id="cancelBooking">Отменить запись</button>':''}</div><p class="flow-hint">${l.flow.booking?`Запись: ${date(l.flow.booking.date)} в ${l.flow.booking.time} · Стамбул. Напоминание менеджеру — за день.`:'Запись пока не создана.'}</p>`;$('#detailBody').prepend(box);$('#flowMessage').value=flowText(l,stage);$('#flowState').textContent=stage==='first'?'Следующий шаг: первый ответ.':stage==='followup'?`Повторных контактов: ${l.flow.followups}/2. Следующий: ${date(l.due)}. В рабочей версии отправка будет привязана к сроку.`:stage==='done'?'Лимит из двух повторных контактов достигнут.':'Клиент ответил или заявка завершена. Повторные сообщения отключены.';
$('#flowSend').onclick=()=>{const current=followStage(l);if(!['first','followup'].includes(current))return;const text=$('#flowMessage').value.trim();if(!text)return toast('Введите текст сообщения');if(current==='first'){l.first=new Date().toISOString();l.status='Написали';l.flow.followups=0;l.due=days(1)}else{l.flow.followups++;l.due=l.flow.followups<2?days(3):''}l.task=l.flow.followups>=2?'Проверить заявку без ответа':'Повторно связаться';logFlow(l,`Демо: ${current==='first'?'первый ответ':'повторный контакт'} — ${text}`);persist();openLead(l.id);toast('Отправка имитирована — клиент ничего не получил')};$('#flowReply').onclick=()=>{if(!l.first)return toast('Сначала имитируйте первый ответ');l.flow.reply=new Date().toISOString();if(!['Консультация','В работе','Закрыта'].includes(l.status))l.status='Ответил';l.task='Согласовать консультацию';l.due=today();logFlow(l,'Демо: клиент ответил. Цепочка повторных контактов остановлена.');persist();openLead(l.id);toast('Ответ клиента имитирован')};$('#bookFlow').onclick=()=>{const d=$('#bookingDate').value,t=$('#bookingTime').value;if(!d||d<today())return toast('Выберите сегодняшнюю или будущую дату');const instant=new Date(`${d}T${t}:00+03:00`);if(instant<=new Date())return toast('Выберите будущее время');l.flow.booking={date:d,time:t};l.status='Консультация';l.task=`Консультация ${t} (Стамбул)`;const remind=new Date(`${d}T12:00:00`);remind.setDate(remind.getDate()-1);l.due=remind.toLocaleDateString('en-CA');logFlow(l,`Демо: консультация ${date(d)} в ${t} (Стамбул). Автосообщения остановлены.`);persist();openLead(l.id);toast('Консультация записана в локальное демо')};if($('#cancelBooking'))$('#cancelBooking').onclick=()=>{l.flow.booking=null;l.status='Ответил';l.task='Согласовать новое время';l.due=today();logFlow(l,'Демо: консультация отменена');persist();openLead(l.id);toast('Запись отменена')};
};
